node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get orders
const orders = db.prepare(\"SELECT order_id, order_date, status, total_paid, address_json FROM orders WHERE customer_id = 'cust_003'\").all();
console.log('=== ORDERS ===');
console.log(JSON.stringify(orders, null, 2));

// Get order items
if (orders.length > 0) {
  const orderIds = orders.map(o => o.order_id);
  const placeholders = orderIds.map(() => '?').join(',');
  const items = db.prepare('SELECT * FROM order_items WHERE order_id IN (' + placeholders + ')').all(...orderIds);
  console.log('\n=== ORDER ITEMS ===');
  console.log(JSON.stringify(items, null, 2));
}
" 2>&1

